c.cpp:
class Solution {
public:
    int minimumLength(string s) {
        bool seen[26] = {};
        int cnt = 0;
        for (char c : s)
            if (!seen[c-'a']) { seen[c-'a'] = true; cnt++; }
        return cnt;
    }
};

