class Solution {
    public int minimumLength(String s) {
        boolean[] seen = new boolean[26];
        int cnt = 0;
        for (char c : s.toCharArray())
            if (!seen[c-'a']) { seen[c-'a'] = true; cnt++; }
        return cnt;
    }
}

