class Solution {
public:
    int minimumLength(string s) {
        unordered_set<char> st(s.begin(), s.end());
        return st.size();
    }
};

c.java:
class Solution {
    public int minimumLength(String s) {
        Set<Character> st = new HashSet<>();
        for (char c : s.toCharArray()) st.add(c);
        return st.size();
    }
}

